-- Полная схема Flowers Crew для новой пустой базы D1 (взята с рабочей базы Brew Crew, уже со всеми поздними колонками).
CREATE TABLE players (tg_id INTEGER PRIMARY KEY, username TEXT, first_name TEXT, lang TEXT, created_at INTEGER NOT NULL, last_seen INTEGER NOT NULL, sessions INTEGER NOT NULL DEFAULT 1, cafe TEXT, city TEXT, level INTEGER DEFAULT 1, money REAL DEFAULT 0, earned REAL DEFAULT 0, rooms INTEGER DEFAULT 1, franchises INTEGER DEFAULT 0, bankrupt INTEGER DEFAULT 0, play_seconds INTEGER DEFAULT 0, referrer INTEGER, ref_claimed INTEGER DEFAULT 0, write_ok INTEGER DEFAULT 0, banned INTEGER DEFAULT 0, best_day REAL DEFAULT 0, snap TEXT, ref_paid INTEGER DEFAULT 0, promo_ban INTEGER, sub_checked INTEGER, badge_name TEXT, goal_cups INTEGER DEFAULT 0, goal_last INTEGER, duel_r INTEGER DEFAULT 1000, duel_w INTEGER DEFAULT 0, duel_l INTEGER DEFAULT 0);
CREATE TABLE admin_ops (id INTEGER PRIMARY KEY AUTOINCREMENT, tg_id INTEGER NOT NULL, op TEXT NOT NULL, amount REAL, text TEXT, created_at INTEGER NOT NULL, applied_at INTEGER, by_admin INTEGER);
CREATE TABLE admin_state (tg_id INTEGER PRIMARY KEY, mode TEXT, data TEXT, chat INTEGER, msg_id INTEGER, at INTEGER);
CREATE TABLE boss (week TEXT, tg_id INTEGER, boss TEXT, pass INTEGER, res TEXT, cafe TEXT, first_name TEXT, at INTEGER, PRIMARY KEY (week, tg_id));
CREATE TABLE cache (key TEXT PRIMARY KEY, val TEXT, at INTEGER);
CREATE TABLE cafe_view (tg_id INTEGER PRIMARY KEY, vk TEXT UNIQUE, data TEXT, at INTEGER, views INTEGER DEFAULT 0, likes INTEGER DEFAULT 0);
CREATE TABLE days (day TEXT NOT NULL, tg_id INTEGER NOT NULL, PRIMARY KEY (day, tg_id));
CREATE TABLE duel (id INTEGER PRIMARY KEY AUTOINCREMENT, a INTEGER NOT NULL, b INTEGER NOT NULL, a_cafe TEXT, b_cafe TEXT, stake INTEGER DEFAULT 0, seed INTEGER NOT NULL, status TEXT NOT NULL, a_score INTEGER, b_score INTEGER, a_det TEXT, b_det TEXT, created_at INTEGER NOT NULL, a_at INTEGER, b_start INTEGER, done_at INTEGER, winner INTEGER, rematch INTEGER DEFAULT 0, posted INTEGER DEFAULT 0, seen_a INTEGER DEFAULT 0, a_run INTEGER NOT NULL DEFAULT 0, b_run INTEGER NOT NULL DEFAULT 0, a_created INTEGER NOT NULL DEFAULT 0, b_created INTEGER NOT NULL DEFAULT 0);
CREATE TABLE goal (id TEXT PRIMARY KEY, total INTEGER DEFAULT 0, updated_at INTEGER);
CREATE TABLE league (tg_id INTEGER PRIMARY KEY, tier INTEGER NOT NULL DEFAULT 0, updated_at INTEGER);
CREATE TABLE league_week (week TEXT NOT NULL, tg_id INTEGER NOT NULL, tier INTEGER NOT NULL DEFAULT 0, profit REAL NOT NULL DEFAULT 0, cafe TEXT, updated_at INTEGER, PRIMARY KEY (week, tg_id));
CREATE TABLE market (id INTEGER PRIMARY KEY AUTOINCREMENT, seller INTEGER, seller_cafe TEXT, staff TEXT, price INTEGER, status TEXT DEFAULT 'open', buyer INTEGER, buyer_cafe TEXT, created_at INTEGER, sold_at INTEGER, staff_id TEXT, seller_run INTEGER NOT NULL DEFAULT 0);
CREATE TABLE market_accounts (tg_id INTEGER PRIMARY KEY, franchises INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 0, roster TEXT NOT NULL DEFAULT '[]', updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE market_operations (operation_id TEXT PRIMARY KEY, tg_id INTEGER NOT NULL, franchises INTEGER NOT NULL, request TEXT NOT NULL, result TEXT NOT NULL, created_at INTEGER NOT NULL, applied_at INTEGER);
CREATE TABLE posts (key TEXT PRIMARY KEY, at INTEGER NOT NULL, ok INTEGER DEFAULT 1, info TEXT, msg_id INTEGER, caption TEXT);
CREATE TABLE promo_tries (tg_id INTEGER NOT NULL, at INTEGER NOT NULL);
CREATE TABLE promo_uses (code TEXT NOT NULL, tg_id INTEGER NOT NULL, at INTEGER NOT NULL, ends_at INTEGER, revoked INTEGER DEFAULT 0, PRIMARY KEY (code, tg_id));
CREATE TABLE promos (code TEXT PRIMARY KEY, kind TEXT NOT NULL, amount REAL DEFAULT 0, style TEXT, legend TEXT, until INTEGER, dur_days INTEGER DEFAULT 7, max_uses INTEGER DEFAULT 0, uses INTEGER DEFAULT 0, active INTEGER DEFAULT 1, created_at INTEGER NOT NULL, by_admin INTEGER);
CREATE TABLE purchases (charge_id TEXT PRIMARY KEY, tg_id INTEGER NOT NULL, item TEXT NOT NULL, stars INTEGER NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER, refunded INTEGER DEFAULT 0, gift_from INTEGER);
CREATE TABLE ref_log (id INTEGER PRIMARY KEY AUTOINCREMENT, tg_id INTEGER, ref INTEGER, src TEXT, res TEXT, at INTEGER);
CREATE TABLE reminders (id INTEGER PRIMARY KEY AUTOINCREMENT, tg_id INTEGER NOT NULL, at INTEGER NOT NULL, text TEXT NOT NULL, sent INTEGER DEFAULT 0, sent_at INTEGER);
CREATE TABLE season (season TEXT NOT NULL, tg_id INTEGER NOT NULL, sp INTEGER DEFAULT 0, cafe TEXT, city TEXT, first_name TEXT, badge INTEGER DEFAULT 0, updated_at INTEGER, PRIMARY KEY (season, tg_id));
CREATE TABLE tour (week TEXT NOT NULL, tg_id INTEGER NOT NULL, profit REAL NOT NULL DEFAULT 0, cafe TEXT, city TEXT, first_name TEXT, updated_at INTEGER, PRIMARY KEY (week, tg_id));
CREATE INDEX admin_ops_user ON admin_ops (tg_id, applied_at);
CREATE INDEX duel_a ON duel(a, created_at);
CREATE INDEX duel_active_players ON duel(a,b,status);
CREATE INDEX duel_b ON duel(b, status);
CREATE INDEX idx_players_ref ON players(referrer);
CREATE INDEX idx_players_seen ON players(last_seen);
CREATE INDEX idx_purchases_user ON purchases(tg_id);
CREATE INDEX idx_rem_at ON reminders(sent, at);
CREATE UNIQUE INDEX market_one_open_staff ON market(seller, seller_run, staff_id) WHERE status = 'open' AND staff_id IS NOT NULL;
CREATE INDEX market_pending_operations ON market_operations(tg_id, applied_at);
CREATE INDEX tour_rank ON tour (week, profit DESC);
